sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float completion;
uniform float start;
uniform float2 center;
uniform float feather;
uniform float direction;
half4 main(float2 coord) {
    float2 d = coord - center * size;
    float a = degrees(atan(d.x, -d.y)) - start;
    if (direction > 0.5) a = -a;
    a = mod(a, 360.0);
    float sweep = clamp(completion, 0.0, 1.0) * 360.0;
    float soft = max(feather, 0.0001);
    float hide = 1.0 - smoothstep(sweep - soft, sweep, a);
    hide *= step(0.0001, sweep);
    if (completion >= 1.0) hide = 1.0;
    return image.eval(coord) * half(1.0 - hide);
}
